with cleaned as (select id, order_id, carrier, delivered_date, cost, status, concat(carrier, '/', status) as carrier_status, coalesce(carrier, 'OTHER') as resolved_carrier from shipments where delivered_date > to_date('2023-06-23') and order_id is not null) select dim.channel, e.status as shipment_status, count(*) as rows_total, min(e.cost) as min_cost from cleaned e join orders dim on e.order_id = dim.id group by grouping sets ((dim.channel, e.status), (dim.channel))
